function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Each menu category is a section that contains a user-items-list
  $('section.page-section:has(.user-items-list)').each((_, secEl) => {
    const $sec = $(secEl);

    // Extract section heading (e.g., PLANTEBASERT, BURGERE, …)
    const $heading = $sec.find('.list-section-title strong');
    const section = $heading.length ? cleanText($heading.text()) : null;

    // Find all dish items inside this section
    $sec.find('ul.user-items-list-simple > li.list-item').each((_, liEl) => {
      const $li = $(liEl);

      // Dish name
      const $nameEl = $li.find('h2.list-item-content__title');
      const name = cleanText($nameEl.text());
      if (!name) return; // skip items without a name

      // Description (first <p> inside the description wrapper)
      const $descEl = $li.find('.list-item-content__description p').first();
      const description = $descEl.length ? cleanText($descEl.text()) : null;

      // Price (inside <strong> of the second <p>)
      const $priceEl = $li.find('.list-item-content__description p strong');
      const priceText = $priceEl.length ? cleanText($priceEl.text()) : '';
      const price = priceText ? parsePrice(priceText) : null;

      // Dedup based on all fields
      const key = `${section ?? ''}|${name}|${description ?? ''}|${price ?? ''}`;
      if (!seen.has(key)) {
        seen.add(key);
        items.push({ section, name, description, price });
      }
    });
  });

  return items;
}
